"""Ten coherent labs: Personalisation, .Rules, Pareto/reporting Skills and a dashboard Skill."""
from copy import deepcopy
import re
from mock_data import EXPECTED as E, ROWS, REPORT
from collections import Counter
from customisation_assets import PERSONAL_PREFS, RULES, PARETO_SKILL, DASHBOARD_SKILL

def expand_labs(base, factory, reporting_skill):
    old={a['num']:deepcopy(a) for a in base}
    mapping={1:1,2:2,3:6,4:6,5:7,6:8,7:9,8:10}
    def remap(value):
        if isinstance(value,str):return re.sub(r'\bLab ([1-8])\b',lambda m:'Lab '+str(mapping[int(m.group(1))]),value)
        if isinstance(value,list):return [remap(v) for v in value]
        if isinstance(value,tuple):return tuple(remap(v) for v in value)
        if isinstance(value,dict):return {k:remap(v) for k,v in value.items()}
        return value
    retained=[]
    for n in [1,2,5,6,7,8]:
        a=remap(old[n]);a['num']=mapping[n];a['duration']={1:35,2:35,5:45,6:45,7:40,8:40}[n];retained.append(a)
    personal=factory(3,2,'Personalise Copilot in Excel for Consistent Service Reports','Personalisation',25,
        'Configure temporary account-level display and explanation preferences, test them in two copies of the same verified Northstar workbook, and distinguish preferences from workbook-specific definitions. A task-specific prompt can supersede Personalisation. Restore your previous settings after the exercise.',
        'Northstar_Personalisation_Test.xlsx, a two-workbook preference comparison and a private note confirming settings restored.',[
        ('Open this lab’s clean data/Northstar_Work_Orders.xlsx and save working copies as Northstar_Personalisation_Test.xlsx and Northstar_Preferences_Copy.xlsx in work-c027. Confirm 120 unique IDs, reporting date 2026-09-30 and cost S$35,827.50. Neither copy needs a .Rules sheet or an installed Skill for this test.','EXCEL - CHAT ONLY:\nInspect tblWorkOrders and Control for Northstar Water Services. State the clean row count, reporting date and recorded cost. Explain why display preferences should not change source values or reporting definitions. Do not edit.'),
        ('In Copilot select Settings (...) > Personalization. Keep your existing settings in a private local note, then temporarily use the four lines in data/Personalisation_Preferences.txt: S$ two decimals, DD-MMM-YYYY, structured references and short explanations. Select Save. Preferences apply to your account on subsequent prompts; they are not stored in or shared with the workbook.',''),
        ('In the first working copy request a small output using your saved preferences. Review the plan before allowing editing. Confirm the date displays 30-Sep-2026 in both copies. Inspect the formulas and number formats in the new Preference_Check sheet; do not accept rounded or rewritten source values.','EXCEL - PLAN:\nPlan a Preference_Check sheet showing Control!B2 reporting date, total work orders and recorded Cost_SGD from tblWorkOrders for Northstar Water Services. Use my saved display and explanation preferences. Preserve Work_Orders, IDs, owners and exact values.\n\nEXCEL - ALLOW EDITING:\nApply the reviewed Preference_Check plan with structured-reference formulas. Show a short explanation first and leave the source unchanged.'),
        ('Open the second copy using the same signed-in account and a new Copilot chat. Do not repeat the preference text in this request. Compare both output displays and formula references; record actual behaviour in data/templates/Customisation_Test_Log.csv. A missed preference is a finding to clarify, not proof of a guaranteed rule.','EXCEL - ALLOW EDITING:\nIn this second Northstar workbook, create Preference_Check with formula-backed Control!B2 reporting date, total work orders and recorded Cost_SGD. Follow my saved preferences, preserve source records and explain the result briefly.'),
        ('Return to the first workbook. Test a specific task instruction that changes only the result display to four decimal places. Verify S$35,827.5000 displays while the numeric value remains 35827.5. Record the comparison; do not alter the saved account settings or source.','EXCEL - ALLOW EDITING:\nFor this task only, display the recorded cost result in Preference_Check with four decimal places. Keep its formula and exact numeric value unchanged. Do not modify source cells or my saved preferences.'),
        ('Explain the scope distinction, log the prompts and your observed checks, then return to Settings (...) > Personalization, restore your previous preferences and Save. Keep the restoration note private; do not upload personal account settings to the shared course folder.','EXCEL - CHAT ONLY:\nExplain which choices in this exercise belong to my account, which belong to this Northstar workbook and which apply only to one prompt. Use the results I actually observed. Do not claim my preferences are shared with another person or added to the workbook.')],
        [('Source controls','Both copies retain120 unique IDs, original owners/statuses and exact cost 35827.50.'),('Display check','Saved S$ two-decimal/date/explanation preferences are checked in two workbooks; observed misses are recorded.'),('Specific request','The output can show35,827.5000 without changing its value or the saved preferences.'),('Restoration','Previous account preferences restored; private baseline note stays outside public courseware.')])
    rules=factory(4,2,'Create and Test Workbook .Rules for Water Service Reporting','Workbook .Rules',35,
        'Turn Northstar’s workbook conventions into a visible .Rules worksheet. Keep one rule per cell in column A, include a formula-driven reporting-date rule, test the output, and verify that the sheet travels with a copied workbook. A .Rules sheet is guidance for Copilot, not Excel formula enforcement or a security boundary.',
        'Northstar_Rules_Workbook.xlsx with visible .Rules column A, a checked Rules_Test output and a copied-workbook sharing check.',[
        ('Open the clean workbook, save as Northstar_Rules_Workbook.xlsx and inspect Control. In Copilot use Add work content > Create workbook rules if offered; otherwise insert a sheet manually and rename it exactly .Rules, including the leading dot. Keep it visible. Rules are fully supported only in English.','EXCEL - CHAT ONLY:\nInspect this Northstar workbook. Identify the source table, fixed reporting date, status vocabulary and current owners. List workbook-specific conventions that belong in .Rules rather than account Personalisation. Do not edit.'),
        ('Open data/Northstar_Workbook_Rules.txt. Copy its lines into .Rules column A with one heading or rule per cell; no data in other columns is required for recognition. Check source preservation, backlog/overdue/rate definitions, S$ display, colours, scope and controlled replacements.','EXCEL - PLAN:\nReview the visible .Rules column A for this Northstar workbook. Identify ambiguous instructions or conflicts with the actual source and Control. Propose concise corrections, keeping one idea per cell. Do not edit the source or invent precedence between rules, preferences and Skills.'),
        ('After reviewing any correction, update only .Rules. Add a formula in the next empty column-A cell: ="Reporting date: "&TEXT(Control!B2,"yyyy-mm-dd"). Recalculate and confirm it displays Reporting date:2026-09-30. Copilot reads the formula result on the next prompt; this does not rewrite dashboard values by itself.','EXCEL - ALLOW EDITING:\nApply only my reviewed .Rules corrections. Keep the sheet visible, one instruction per column-A cell, and retain the reporting-date formula. Preserve source data, Control and unrelated sheets.'),
        ('Request a Rules_Test summary without restating the formatting rules. Check counts against Control, source references, displayed date/scope, S$ units and proposal wording. The known baseline is120 total,60 backlog,50 overdue and 30/48 on-time Closed.','EXCEL - ALLOW EDITING:\nCreate Rules_Test for Northstar Water Services from tblWorkOrders using the visible workbook .Rules. Include total, backlog, overdue, on-time Closed rate and recorded cost with formula/source evidence. Show date and All scope. Keep source owners and values unchanged.'),
        ('Save As Northstar_Rules_Shared_Copy.xlsx. Open the copy and confirm .Rules is still present and visible in column A; you have not exported your account preferences. If testing a hidden sheet, use only a sandbox copy, hide .Rules, record that hidden rules are not used, then unhide before continuing. Do not claim native rule use when the feature is unavailable.','EXCEL - CHAT ONLY:\nIn this copied Northstar workbook, identify the visible .Rules instructions and reporting-date formula result. Explain which guidance travels with the workbook and which account preferences do not. Verify Rules_Test against Control without changing records.'),
        ('Record the sheet name, visibility, column, formula result, actual output checks and copied-workbook check in data/templates/Customisation_Test_Log.csv. Carry the rules-enabled workbook forward. If a prompt, Skill and rule disagree, ask for clarification and verify the output; no universal precedence is assumed.','EXCEL - CHAT ONLY:\nCompare Personalisation, .Rules and a reusable Skill for Northstar reporting. Place currency preferences, this workbook’s backlog/date rules and the repeatable Pareto workflow in the right scope. Identify conflicts requiring clarification and the checks a person still must perform.')],
        [('Recognition','Exactly .Rules; visible worksheet; instructions in column A, one idea per cell.'),('Formula rule','Reporting-date formula recalculates and displays2026-09-30; no source values changed.'),('Output controls','120 total;60 backlog;50 overdue;30/48 on-time;S$35,827.50 at All scope.'),('Workbook copy','Visible .Rules travels with the copy; account preferences are not exported.')],prereq=['Lab 3 scope comparison; verified Lab1 clean source or supplied checkpoint.'])
    counts=Counter(r[2] for r in ROWS if r[4] not in ('Closed','Cancelled') and r[7]<REPORT)
    ordered=sorted(counts.items(),key=lambda kv:(-kv[1],kv[0]));expected='; '.join(f'{k}={v}' for k,v in ordered)
    pareto=factory(5,2,'Create a Custom Pareto Chart Skill and Apply It','Custom Pareto Chart Skill',40,
        'Author water-service-pareto/SKILL.md with Copilot, install it in Excel and apply it to the same overdue work-order queue. Build a descending count chart plus cumulative-percentage line, then check a controlled rerun and a second grouping. Contribution analysis does not establish root cause or force an 80/20 split.',
        'water-service-pareto/SKILL.md, Northstar_Pareto.xlsx with Pareto_Job_Category and Pareto_Site, and a verified rerun record.',[
        ('Open your rules-enabled workbook from Lab 4 or this lab’s clean rules-enabled data/Northstar_Work_Orders.xlsx. Save as Northstar_Pareto.xlsx. Read data/Pareto_Expected_Controls.json and the supplied Skill template before drafting your own file. Work only with synthetic data.','EXCEL - CHAT ONLY:\nFor tblWorkOrders at Control!B2, All sites, count overdue backlog by Job_Category: Status neither Closed nor Cancelled and Due_Date strictly before the reporting date. Show category counts and total before charting. Preserve all records.'),
        ('In Microsoft 365 Copilot on the web at https://copilot.cloud.microsoft, provide this self-contained specification. Copy the complete response into a plain-text editor and save UTF-8 SKILL.md inside a matching water-service-pareto folder. Compare it to data/templates/water-service-pareto/SKILL.md. If short of time, use the reviewed supplied file and record that choice.','MICROSOFT 365 COPILOT WEB:\nWrite a complete SKILL.md named water-service-pareto for a recurring water-pipe service report. Require YAML name and description, actual source table, reporting date, scope, count metric and grouping column. Source tblWorkOrders has Work_Order_ID, Job_Category, Site, Status and Due_Date. Overdue backlog excludes Closed/Cancelled and has Due_Date before the supplied date. Read visible workbook .Rules; preserve source IDs/statuses/owners and unrelated sheets. Count by grouping, sort count descending then label alphabetically for ties, and create formula-backed count, cumulative count, share and cumulative percentage. Build an editable combo chart: count columns and cumulative line on a 0%-100% right axis. Output only Pareto_<grouping column>; ask before replacing the matching output, rerun without duplicates, and leave zero-total percentages N/A. Verify counts, stable ties and final 100%; do not infer causes or force 80/20. Return the entire file.'),
        ('In Excel use Copilot Settings (...) > Manage plugins & skills > Custom skills > Create OneDrive folder if needed > Open skills folder. Copy water-service-pareto/SKILL.md into that app-created location, Refresh and enable it. Verify the name using Choose plugins & skills or @mention. If unavailable, paste the complete reviewed Skill before each request, remove @water-service-pareto and record Manual practice - native Skill unavailable. Log web authoring manually.',''),
        ('Request a plan before building. Confirm the eligible total 50 and the five ordered category counts. After review, apply the Skill. Inspect Pareto_Job_Category, formulas, axes and source preservation; copying a static image does not meet the editable-chart goal.','EXCEL - PLAN:\n@water-service-pareto Plan an overdue-backlog Pareto Chart by Job_Category from tblWorkOrders at 2026-09-30, All sites. Follow visible .Rules. Explain summary formulas, descending counts, alphabetical ties, cumulative percentages and the named output to create. Do not edit yet.\n\nEXCEL - ALLOW EDITING:\n@water-service-pareto Apply the reviewed Job_Category Pareto plan. Create Pareto_Job_Category with a formula-backed summary and editable count-column/cumulative-percent-line combo chart. Keep source data and unrelated sheets unchanged.'),
        ('Check counts against the supplied controls. Verify cumulative percentages 36%,60%,76%,92%,100% and two equal8-count categories in alphabetical order. The first four categories reach at least80%; do not call this proof that20% of categories cause80% of failures. If combo chart UI is absent, select the summary and use Insert > Combo > Custom Combination: Count clustered column, Cumulative_Percent line on secondary axis, right bounds 0 and 1; label both axes. Record a missing feature honestly.','EXCEL - CHAT ONLY:\nVerify Pareto_Job_Category against eligible source rows. Check total 50, descending counts, alphabetical tie order, cumulative percentages 36/60/76/92/100%, final 100% and labelled dual axes. State which category set first reaches 80%, and why this is contribution rather than a causal diagnosis.'),
        ('Save a sandbox copy, rerun the same grouping after approving replacement of only Pareto_Job_Category, and compare source IDs/statuses/owners and sheet/chart counts. Then apply the Skill to Site to produce a distinct Pareto_Site output. Keep both reviewed summaries for later decision evidence.','EXCEL - PLAN:\n@water-service-pareto Refresh the existing Pareto_Job_Category for the same source, date and All scope. Identify exactly what will be replaced and ask before replacement. Preserve every unrelated sheet and do not duplicate charts.\n\nEXCEL - ALLOW EDITING:\n@water-service-pareto After the approved category rerun, create a separate overdue-backlog Pareto_Site for the same source/date/scope. Preserve Pareto_Job_Category and reconcile the new summary to 50 overdue orders.')],
        [('Eligible population','Overdue backlog50; no Closed or Cancelled records included.'),('Category counts',expected),('Cumulative percentages','36%,60%,76%,92%,100%; Leak Repair precedes Valve Repair in the8-count tie.'),('Chart and rerun','Editable columns plus cumulative line; right axis0%-100%; matching output replaced only after review, without duplicates.'),('Source and interpretation','120 original records preserved; Site grouping also totals50; no invented root cause.')],prereq=['Lab 4 visible .Rules and clean source; assigned Excel Skill feature checked.'])
    pareto['extra_files']=[('data/templates/water-service-pareto/SKILL.md',PARETO_SKILL,'Reviewed Pareto Skill fallback')]
    report=deepcopy(remap(old[4]));report['num']=6;report['duration']=40;report['title']='Create, Use and Improve the Maintenance Reporting Skill';report['theme']='Reporting Skill';report['desc']='Reuse the Skill-authoring and installation method from Lab 5 to create maintenance-reporting. Apply it in Excel and PowerPoint, test missing inputs and a controlled rerun, then refine v2 using actual evidence. The supplied reviewed template supports rejoining; it is not proof of native execution.'
    report['prerequisites']=['Labs 1–2 verified brief and four-slide update; Lab 5 Skill-authoring method.']
    report['steps']=[
        ('Use Microsoft 365 Copilot on the web to draft maintenance-reporting/SKILL.md from the complete specification below. Review it against data/templates/maintenance-reporting/SKILL.md, save the complete file as v1 in work-c027, then install it using the same Excel app-created custom Skills folder and Refresh route practised in Lab5. If a native Skill menu is missing, use the full reviewed file as pasted instructions, remove @mention and label the route manual.','MICROSOFT 365 COPILOT WEB:\nWrite complete maintenance-reporting SKILL.md with YAML name/description. Require actual tblWorkOrders or a verified Word snapshot, report date and filter scope. Respect visible .Rules. Define backlog, overdue and Closed-only on-time rate. Preserve IDs/statuses/current owners; keep assignment proposals separate and approvals UNKNOWN. Create a verified Excel summary and improve a supplied four- or eight-slide PowerPoint report from selected evidence. Ask for missing inputs and before replacing only named outputs; rerun without duplicates or source changes. Keep the existing design and source/date notes. Never send email or approve assignments. Return the entire file.'),
        *report['steps'][:3],
        ('In PowerPoint select the reviewed Word snapshot and open the four-slide update from Lab2 or data/checkpoints/Northstar_Initial_Update_Checkpoint.pptx. Use Copilot > + > Choose skills > Manage skills > Add skill to upload the reviewed maintenance-reporting file, or use the app’s own supported Skills folder. Verify it in PowerPoint separately from Excel. If missing, paste the complete reviewed Skill plus snapshot as manual instructions and remove @mention. Apply the following refinement after review.','POWERPOINT COPILOT:\n@maintenance-reporting Improve this existing four-slide Northstar update from the selected verified Word snapshot. Preserve slide count, all values and source/date/scope notes; use clear claim headlines and the existing design. Keep assignment suggestions explicitly proposed and do not assume access to Excel chat.'),
        *report['steps'][4:]
    ]
    report['extra_files']=[('data/templates/maintenance-reporting/SKILL.md',reporting_skill,'Reviewed reporting Skill fallback')]
    dash=[a for a in retained if a['num']==7][0];dash['title']='Create and Apply a Custom Interactive Dashboard Skill';dash['theme']='Custom Dashboard Skill';dash['desc']='Create water-service-dashboard/SKILL.md for the Northstar maintenance workflow, install it in Excel, then invoke it to plan and build an interactive dashboard. Six KPIs and three charts share four filter selections. Workbook .Rules supplies scope, display and review constraints; the Skill supplies the repeatable method.'
    author=('Open the synthetic source and data/templates/water-service-dashboard/SKILL.md. In Microsoft 365 Copilot on the web draft the full reusable Skill from this specification. Save it inside a matching water-service-dashboard folder and review every guard/measure before installation. Log the web prompt manually.','MICROSOFT 365 COPILOT WEB:\nWrite complete water-service-dashboard SKILL.md with YAML name/description. Require actual tblWorkOrders and report date in Control!B2; read visible .Rules. Preserve source IDs/statuses/owners, Technicians, Control, .Rules, Prompt_Log, Pareto_* and unrelated sheets. Plan first and ask before replacing only named dashboard outputs; rerun without duplicated charts. Dashboard B2:B5 select Site, Job_Category, Status, Assigned_To with All bypasses and AND logic. B7 total, B8 backlog excluding Closed/Cancelled, B9 backlog Due_Date before Control!B2, B10 Closed, B11 on-time Closed_Date<=Due_Date among Closed only with N/A if none, B12 recorded Cost_SGD across selected statuses. Create three formula-backed editable status/category/site charts sharing the exact filter scope. Use structured references, not fixed120-row ranges, and white/navy/blue/teal workbook design. Baseline check at 2026-09-30 All:120 total,48 Closed,12 Cancelled,60 backlog,50 overdue,30/48 on-time,35827.50 cost. Verify site/no-Closed/no-row tests, source preservation and a separate two-row append sandbox with 122 total,49 Closed,61 backlog,51 overdue,31/49 on-time and 36227.50 cost. These are snapshot tests, not universal future figures. Ask for missing inputs; never approve assignments, infer causes/savings or send email. Return the entire file.')
    install=('Use Excel Settings (...) > Manage plugins & skills > Custom skills > Open skills folder (Create OneDrive folder if needed). Copy the reviewed water-service-dashboard folder into that app-created location, Refresh, enable and verify its exact name in Choose plugins & skills. If unavailable, paste the entire reviewed Skill before each prompt, remove @water-service-dashboard and record Manual practice - native Skill unavailable. Installing maintenance-reporting or water-service-pareto does not install this distinct Skill.','')
    dash['steps']=[author,install]+dash['steps']
    dash['steps']=[(i,re.sub(r'(EXCEL - [A-Z ]+:\n)(?!@water-service-dashboard)',r'\1@water-service-dashboard ',c) if c.startswith('EXCEL - ') else c) for i,c in dash['steps']]
    dash['extra_files']=[('data/templates/water-service-dashboard/SKILL.md',DASHBOARD_SKILL,'Reviewed interactive dashboard Skill fallback')]
    interaction=[a for a in retained if a['num']==8][0];interaction['title']='Use the Dashboard Skill for Filters, Refresh and Safe Reruns';interaction['theme']='Interactive Filters and Refresh';interaction['prerequisites'].append('Lab 7 reviewed water-service-dashboard Skill installed or explicitly labelled manual route.')
    interaction['steps']=[(i,re.sub(r'(EXCEL - [A-Z ]+:\n)(?!@water-service-dashboard)',r'\1@water-service-dashboard ',c) if c.startswith('EXCEL - ') else c) for i,c in interaction['steps']]
    interaction['extra_files']=[('data/templates/water-service-dashboard/SKILL.md',DASHBOARD_SKILL,'Reviewed dashboard Skill for reruns')]
    interaction['steps'].insert(-1,('In the sandbox workbook request a controlled Skill rerun after the append. Review the named replacement areas, then approve only those areas. Verify one dashboard, three charts, original 120 source rows unchanged and both legitimate new rows retained. Keep the 120-row baseline separate for Lab 9.','EXCEL - PLAN:\n@water-service-dashboard Refresh the existing dashboard for the sandbox 122-row table and same reporting date. Preserve all original source records, both new rows, .Rules, Pareto_* and unrelated sheets. Identify named output replacements and ask before editing; keep one dashboard and three charts.\n\nEXCEL - ALLOW EDITING:\n@water-service-dashboard Apply only the reviewed sandbox dashboard rerun. Retain the chosen source/date and make every KPI and chart follow the four filters; reconcile 122 total,61 backlog,51 overdue,49 Closed,31/49 on-time and S$36,227.50. Do not alter the untouched baseline workbook.'))
    final=sorted(retained+[personal,rules,pareto,report],key=lambda a:a['num'])
    for a in final:
        if a['topic']==2:a['objective']='LO2: distinguish account Personalisation, workbook .Rules and reusable Skills; configure, apply and verify each using water-service evidence.'
        a['goal']=a['desc']
        if a['num'] in (3,4):a['services']='Microsoft 365 Copilot in Excel · OneDrive'
        if a['num'] in (5,7,8):a['services']='Excel Copilot · Microsoft 365 Copilot web · OneDrive'
        if a['num']==6:a['services']='Excel and PowerPoint Copilot · Microsoft 365 Copilot web · OneDrive'
        a['sample_prompts']=[('Scope','State actual source, report date and selected scope before acting.'),('Verify','Explain the source/formula checks and preserve unknowns and original records.')]
    assert [a['num'] for a in final]==list(range(1,11))
    return final
